# Let me identify scattered dots vs rectangles

def is_scattered_dot(r, c, grid, bg):
    """Check if a non-bg cell is a scattered dot (surrounded by bg or different color)"""
    val = grid[r][c]
    if val == bg:
        return False

    # Check all 8 neighbors
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                neighbors.append((nr, nc, grid[nr][nc]))

    # Count neighbors with same value
    same_count = sum(1 for _, _, v in neighbors if v == val)

    # A scattered dot has few or no same-colored neighbors
    # A rectangle edge has more same-colored neighbors
    return same_count <= 2

